"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["97106"],{46569(e){e.exports=JSON.parse('{"id":"FIN-1323","slug":"decentralized-finance","term":"Decentralized Finance (DeFi)","also_known_as":["DeFi"],"difficulty":"Advanced","definition":"Decentralized finance (DeFi) refers to financial services, such as lending, borrowing, trading and earning interest, that are provided through software programs running on public blockchains, without traditional intermediaries such as banks or brokers.","explanation":["DeFi applications use smart contracts, self-executing programs on blockchains such as Ethereum, to carry out financial transactions automatically according to pre-set rules. Users interact with them directly using crypto wallets.","Common DeFi services include decentralized exchanges, where users trade tokens with each other through automated pools of funds; lending platforms, where users deposit crypto to earn interest or borrow against collateral; and stablecoins and derivatives.","For example, a user could deposit cryptocurrency into a DeFi lending protocol as collateral and borrow a stablecoin against it, without any credit check, with the loan automatically liquidated if the collateral\'s value falls too far.","Supporters see DeFi as more open, transparent and accessible than traditional finance. But it carries serious risks: bugs in smart contracts, hacks, extreme price volatility, fraud, lack of consumer protection and unclear regulation. Billions of dollars have been lost through exploits. Despite the name, many DeFi projects remain controlled by small groups of developers or token holders."],"note":"","total":1500,"prev":{"slug":"debt-to-income-ratio","term":"Debt-to-Income Ratio"},"next":{"slug":"deductible","term":"Deductible"}}')}}]);